@Test
public void testParse() throws Exception {
    assertThat(parse(""), NameValuePairListMatcher.isEmpty());
    assertThat(parse("Name0"), NameValuePairListMatcher.equalsTo(new BasicNameValuePair("Name0", null)));
    assertThat(parse("Name1=Value1"), NameValuePairListMatcher.equalsTo(new BasicNameValuePair("Name1", "Value1")));
    assertThat(parse("Name2="), NameValuePairListMatcher.equalsTo(new BasicNameValuePair("Name2", "")));
    assertThat(parse(" Name3  "), NameValuePairListMatcher.equalsTo(new BasicNameValuePair("Name3", null)));
    assertThat(parse("Name4=Value%204%21"), NameValuePairListMatcher.equalsTo(new BasicNameValuePair("Name4", "Value 4!")));
    assertThat(parse("Name4=Value%2B4%21"), NameValuePairListMatcher.equalsTo(new BasicNameValuePair("Name4", "Value+4!")));
    assertThat(parse("Name4=Value%204%21%20%214"), NameValuePairListMatcher.equalsTo(new BasicNameValuePair("Name4", "Value 4! !4")));
    assertThat(parse("Name5=aaa&Name6=bbb"), NameValuePairListMatcher.equalsTo(new BasicNameValuePair("Name5", "aaa"), new BasicNameValuePair("Name6", "bbb")));
    assertThat(parse("Name7=aaa&Name7=b%2Cb&Name7=ccc"), NameValuePairListMatcher.equalsTo(new BasicNameValuePair("Name7", "aaa"), new BasicNameValuePair("Name7", "b,b"), new BasicNameValuePair("Name7", "ccc")));
    assertThat(parse("Name8=xx%2C%20%20yy%20%20%2Czz"), NameValuePairListMatcher.equalsTo(new BasicNameValuePair("Name8", "xx,  yy  ,zz")));
    assertThat(parse("price=10%20%E2%82%AC"), NameValuePairListMatcher.equalsTo(new BasicNameValuePair("price", "10 \u20AC")));
    assertThat(parse("a=b\"c&d=e"), NameValuePairListMatcher.equalsTo(new BasicNameValuePair("a", "b\"c"), new BasicNameValuePair("d", "e")));
    assertThat(parse("russian=" + PercentCodec.encode(RU_HELLO, StandardCharsets.UTF_8) + "&swiss=" + PercentCodec.encode(CH_HELLO, StandardCharsets.UTF_8)), NameValuePairListMatcher.equalsTo(new BasicNameValuePair("russian", RU_HELLO), new BasicNameValuePair("swiss", CH_HELLO)));
}

@Test
public void testFormat() throws Exception {
    assertThat(format(new BasicNameValuePair("Name0", null)), CoreMatchers.equalTo("Name0"));
    assertThat(format(new BasicNameValuePair("Name1", "Value1")), CoreMatchers.equalTo("Name1=Value1"));
    assertThat(format(new BasicNameValuePair("Name2", "")), CoreMatchers.equalTo("Name2="));
    assertThat(format(new BasicNameValuePair("Name4", "Value 4&")), CoreMatchers.equalTo("Name4=Value+4%26"));
    assertThat(format(new BasicNameValuePair("Name4", "Value+4&")), CoreMatchers.equalTo("Name4=Value%2B4%26"));
    assertThat(format(new BasicNameValuePair("Name4", "Value 4& =4")), CoreMatchers.equalTo("Name4=Value+4%26+%3D4"));
    assertThat(format(new BasicNameValuePair("Name5", "aaa"), new BasicNameValuePair("Name6", "bbb")), CoreMatchers.equalTo("Name5=aaa&Name6=bbb"));
    assertThat(format(new BasicNameValuePair("Name7", "aaa"), new BasicNameValuePair("Name7", "b,b"), new BasicNameValuePair("Name7", "ccc")), CoreMatchers.equalTo("Name7=aaa&Name7=b%2Cb&Name7=ccc"));
    assertThat(format(new BasicNameValuePair("Name8", "xx,  yy  ,zz")), CoreMatchers.equalTo("Name8=xx%2C++yy++%2Czz"));
    assertThat(format(new BasicNameValuePair("russian", RU_HELLO), new BasicNameValuePair("swiss", CH_HELLO)), CoreMatchers.equalTo("russian=" + PercentCodec.encode(RU_HELLO, StandardCharsets.UTF_8) + "&swiss=" + PercentCodec.encode(CH_HELLO, StandardCharsets.UTF_8)));
}

